-- # Lernfeld 5: Cyberphysische Systeme > ## IT-Sicherheit > - Sicherheit > - + DSGVO

INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Gilt die DSGVO ausschließlich für Unternehmen mit Sitz in der Europäischen Union?', 2, '[{"text": "Nein", "correct": true, "because": "Sie gilt auch für Firmen außerhalb der EU, die Daten von EU-Bürgern verarbeiten"}, {"text": "Ja", "correct": false, "because": "Anwendung ist extraterritorial"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann die DSGVO ohne technische Maßnahmen wie Verschlüsselung vollständig eingehalten werden?', 2, '[{"text": "Nein", "correct": true, "because": "Technische Sicherheitsmaßnahmen sind vorgeschrieben"}, {"text": "Ja", "correct": false, "because": "Datenschutz erfordert Technik"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen personenbezogene Daten gemäß DSGVO immer verschlüsselt gespeichert werden?', 2, '[{"text": "Nein", "correct": true, "because": "Verschlüsselung ist eine Option, nicht Pflicht"}, {"text": "Ja", "correct": false, "because": "Flexibilität bei Maßnahmen erlaubt"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist eine Verletzung der DSGVO automatisch mit einer Geldstrafe verbunden?', 2, '[{"text": "Nein", "correct": true, "because": "Sanktionen hängen vom Einzelfall ab"}, {"text": "Ja", "correct": false, "because": "Strafen sind nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann die DSGVO Unternehmen dazu zwingen, Daten außerhalb der EU zu speichern?', 2, '[{"text": "Nein", "correct": true, "because": "DSGVO regelt Speicherort nicht direkt"}, {"text": "Ja", "correct": false, "because": "Ort ist nicht vorgeschrieben"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahme ist gemäß DSGVO zwingend bei einer Datenpanne erforderlich?', 2, '[{"text": "Meldung an die Aufsichtsbehörde", "correct": true, "because": "Innerhalb 72 Stunden vorgeschrieben"}, {"text": "Datenwiederherstellung", "correct": false, "because": "Nicht zwingend"}, {"text": "Öffentliche Bekanntgabe", "correct": false, "because": "Nur bei Risiko"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Recht gewährt die DSGVO den Betroffenen primär in Bezug auf ihre Daten?', 3, '[{"text": "Recht auf Löschung", "correct": true, "because": "Auch als Recht auf Vergessen bekannt"}, {"text": "Recht auf Speicherung", "correct": false, "because": "Kein DSGVO-Recht"}, {"text": "Recht auf Veröffentlichung", "correct": false, "because": "Nicht enthalten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Strafe droht bei schwerwiegenden DSGVO-Verstößen maximal?', 2, '[{"text": "20 Millionen Euro oder 4% des Jahresumsatzes", "correct": true, "because": "Höherer Wert gilt"}, {"text": "10.000 Euro", "correct": false, "because": "Zu niedrig"}, {"text": "1 Million Euro", "correct": false, "because": "Unter Maximum"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle ist gemäß DSGVO für die Umsetzung der Vorschriften in Unternehmen verantwortlich?', 2, '[{"text": "Datenschutzbeauftragter", "correct": true, "because": "Überwacht Einhaltung"}, {"text": "IT-Administrator", "correct": false, "because": "Technische Rolle"}, {"text": "Geschäftsführer", "correct": false, "because": "Nicht spezifisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Prinzip der DSGVO fordert, dass nur notwendige Daten erhoben werden?', 2, '[{"text": "Datenminimierung", "correct": true, "because": "Nur erforderliche Daten"}, {"text": "Transparenz", "correct": false, "because": "Fokus auf Information"}, {"text": "Zweckbindung", "correct": false, "because": "Fokus auf Nutzung"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Rechte haben Betroffene gemäß DSGVO?', 4, '[{"text": "Recht auf Auskunft", "correct": true, "because": "Einblick in Daten"}, {"text": "Recht auf Berichtigung", "correct": true, "because": "Korrektur falscher Daten"}, {"text": "Recht auf Datenportabilität", "correct": true, "because": "Datenübertragung"}, {"text": "Recht auf Verkauf", "correct": false, "because": "Kein DSGVO-Recht"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche technischen Maßnahmen unterstützt die DSGVO zur Datensicherheit?', 3, '[{"text": "Verschlüsselung", "correct": true, "because": "Schutz der Vertraulichkeit"}, {"text": "Pseudonymisierung", "correct": true, "because": "Reduziert Identifizierbarkeit"}, {"text": "Datenvervielfältigung", "correct": false, "because": "Kein Sicherheitsaspekt"}, {"text": "Zugangskontrollen", "correct": true, "because": "Schützt vor unbefugtem Zugriff"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Pflichten haben Unternehmen gemäß DSGVO bei der Datenverarbeitung?', 3, '[{"text": "Verzeichnis der Verarbeitungstätigkeiten", "correct": true, "because": "Dokumentation erforderlich"}, {"text": "Einwilligung der Betroffenen", "correct": true, "because": "Rechtsgrundlage nötig"}, {"text": "Automatische Datenlöschung", "correct": false, "because": "Nicht zwingend"}, {"text": "Datenschutz-Folgenabschätzung", "correct": true, "because": "Bei hohem Risiko"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte der DSGVO könnten Unternehmen irrtümlich übersehen?', 4, '[{"text": "Meldepflicht bei Datenpannen", "correct": true, "because": "72-Stunden-Frist"}, {"text": "Recht auf Datenportabilität", "correct": true, "because": "Technisch komplex"}, {"text": "Pflicht zur Datenmaximierung", "correct": false, "because": "Gegenteil gilt"}, {"text": "Extraterritoriale Anwendung", "correct": true, "because": "Auch außerhalb EU"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Prinzipien der DSGVO sind für die Datensicherheit zentral?', 3, '[{"text": "Rechtmäßigkeit", "correct": true, "because": "Legale Grundlage nötig"}, {"text": "Integrität und Vertraulichkeit", "correct": true, "because": "Schutz vor Verlust"}, {"text": "Unbegrenzte Speicherung", "correct": false, "because": "Speicherbegrenzung gilt"}, {"text": "Zweckbindung", "correct": true, "because": "Daten nur für Zweck"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Die DSGVO erlaubt die Datenverarbeitung nur mit Einwilligung. b) Unternehmen müssen Datenpannen immer öffentlich melden.', 3, '[{"text": "Beides falsch", "correct": true, "because": "Andere Rechtsgrundlagen möglich, Öffentlichkeit nicht zwingend"}, {"text": "Nur a) stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "Beides falsch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Die DSGVO verlangt einen Datenschutzbeauftragten in jedem Unternehmen. b) Betroffene können Datenlöschung verlangen.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Datenschutzbeauftragter nicht immer, Löschung möglich"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Die DSGVO gilt auch für nicht-digitale Daten. b) Strafen sind bei jedem Verstoß unvermeidbar.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch Papierdaten, Strafen nicht automatisch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Die DSGVO schreibt Verschlüsselung als Pflichtmaßnahme vor. b) Datenportabilität erfordert maschinenlesbare Formate.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Verschlüsselung optional, Portabilität strukturiert"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Die DSGVO erlaubt unbegrenzte Datenspeicherung bei Einwilligung. b) Unternehmen außerhalb der EU sind von der DSGVO ausgenommen.', 3, '[{"text": "Beides falsch", "correct": true, "because": "Speicherbegrenzung gilt, extraterritoriale Wirkung"}, {"text": "Nur a) stimmt", "correct": false, "because": "a) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "Beides falsch"}]');
